// Lab X2.4 (milestone M9): the quantised model, your entry points, and the pieces you call.
// Provided; you do not edit this file.
//
// Lab 22.2's decode step (M8) with its weights stored in llama.cpp's block formats:
//
//   embed       H[r][j] = dequantise(E)[tokens[r]][j]              (yours: a dequantising gather)
//   per layer   T = H W_l^T,  T += b_l,  H += T                     (your QLinear, then M0, M0)
//   LM head     logits = H E^T                                      (your QLinear, with E)
//   sampler     probs = softmax(logits / temperature), tokens = argmax(logits)       (M4)
//
// Every weight matrix is stored (out, in), row-major, as nn.Linear and ggml store it, in one of
// three formats (../shared-g12/qformats.h has the layouts and the CPU rules, notes/today/
// x2-facts.md D1):
//   QF_F32   f32[rows * cols]                       float32
//   QF_Q8_0  q8[rows * cols]                        int8 codes, row-major
//            q8d[rows * cols / 32]                  FP16 bits of one scale per 32 codes of a row
//                                                   weight = code * scale
//   QF_Q4_0  q4[rows * cols / 32]                   llama.cpp's 18-byte block_q4_0, row-major;
//                                                   byte j of a block: weight j (low nibble),
//                                                   weight j + 16 (high nibble);
//                                                   weight = (code - 8) * scale
// cols is a multiple of 32. The biases, the activations and the outputs stay float32, batch
// first. Not in the book: module X2 is ours; the formats are llama.cpp's.
#pragma once
#include <cstdint>

#include "../shared-g12/qformats.h"              // BlockQ4_0, QK4_0, and the CPU quantisers
#include "../../ch22/lab2_batching/decode.h"     // DecodeState, and lab 22.2's pieces (M0, M4)

enum QFormat { QF_F32 = 0, QF_Q8_0 = 1, QF_Q4_0 = 2 };

// The GEMVs this step calls are matrix-vector kernels: they keep one running sum per batch row
// in registers and stop at 8 rows, as lab 22.1's gather and llama.cpp's mmvq do (ch22-facts D3).
#define QDECODE_MAX_BATCH 8

#if !defined(__OBJC__)
// ---------------------------------------------------------------- CUDA, HIP, emulators
struct QMatrix {
    QFormat fmt;
    int rows, cols;                // (out, in)
    const float* f32;              // QF_F32, else null. Device pointers.
    const int8_t* q8;              // QF_Q8_0, else null
    const uint16_t* q8d;           // QF_Q8_0, else null
    const BlockQ4_0* q4;           // QF_Q4_0, else null
};

struct QDecodeModel {
    int d;                         // hidden size, a multiple of 32
    int vocab;                     // vocabulary size
    int layers;
    QMatrix E;                     // [vocab x d]: the embedding, and the LM head's weight (tied)
    const QMatrix* W;              // W[l], l < layers: [d x d], (out, in). A host array.
    const float* const* b;         // b[l]: device pointer to a [d] float bias. A host array.
};

// ---- yours, in <variant>/kernel.cu ----
// H[r][j] = the dequantised E[tokens[r]][j], for r < batch, j < E.cols: one thread per element
// of H, reading its block's scale. Bit for bit the value the CPU's dequantiser gives.
void launchEmbedQ(const QMatrix& E, const int* tokens, float* H, int batch);
// Y[batch x W.rows] = X[batch x W.cols] W^T, dispatched by W.fmt to the GEMV for that format.
// batch <= QDECODE_MAX_BATCH.
void launchQLinear(const float* X, const QMatrix& W, float* Y, int batch);
// One greedy decode step for s.batch sequences: one launch per operation for the whole
// batch, nothing waiting inside.
void launchQDecodeStep(const QDecodeModel& m, DecodeState& s);

// ---- provided: reference solutions of earlier labs, built beside yours ----
// Each is Y[batch x out] = X[batch x in] W^T with W (out, in), batch <= 8, launched and not
// waited for. Lab 22.1's gather (float32 weights):
void launchGemvGather(const float* X, const float* W, float* Y, int batch, int in, int out);
// Lab X2.1 (Q8_0 codes and scales in two arrays; in % 32 == 0):
void launchGemvQ8_0(const float* X, const int8_t* Wq, const uint16_t* Wd, float* Y, int batch, int in, int out);
// Lab X2.2 (Q4_0 blocks; in % 32 == 0):
void launchGemvQ4_0(const float* X, const BlockQ4_0* W, float* Y, int batch, int in, int out);
// decode.h declares the rest: launchAddBias, launchAddResidual (lab 2.3, M0) and
// launchSoftmaxRows, launchArgmaxRows (lab 10.3, M4).

#else
// ---------------------------------------------------------------- Metal
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

struct QMatrix {
    QFormat fmt;
    uint32_t rows, cols;           // (out, in)
    id<MTLBuffer> f32;             // QF_F32, else nil
    id<MTLBuffer> q8, q8d;         // QF_Q8_0, else nil
    id<MTLBuffer> q4;              // QF_Q4_0, else nil
};

// Compiled by the driver, each from its own lab's kernel.metal with the constants that lab's
// driver uses.
struct QPipelines {
    id<MTLComputePipelineState> embedF32, embedQ8_0, embedQ4_0;   // your kernel.metal
    id<MTLComputePipelineState> gemvF32;                         // lab 22.1's gemv_gather
    id<MTLComputePipelineState> gemvQ8_0;                        // lab X2.1's gemv_q8_0
    id<MTLComputePipelineState> gemvQ4_0;                        // lab X2.2's gemv_q4_0
    id<MTLComputePipelineState> addBias, addResidual;            // lab 2.3's
    id<MTLComputePipelineState> softmax, argmax;                 // lab 10.3's
};

struct QDecodeModel {
    uint32_t d, vocab, layers;
    QMatrix E;                     // [vocab x d], also the LM head's weight
    const QMatrix* W;              // W[l]: [d x d], (out, in). A host array.
    NSArray<id<MTLBuffer>>* b;     // b[l]: [d] float
    QPipelines pipelines;
};

// ---- yours, in <variant>/launch.mm (the embedding kernels are in <variant>/kernel.metal) ----
// Each puts its dispatches into `enc`, which the caller opened (a serial encoder) and will
// end, commit and wait for: the whole step is one command buffer.
void encodeEmbedQ(id<MTLComputeCommandEncoder> enc, const QPipelines& p, const QMatrix& E, id<MTLBuffer> tokens,
                  id<MTLBuffer> H, uint32_t batch);
void encodeQLinear(id<MTLComputeCommandEncoder> enc, const QPipelines& p, id<MTLBuffer> X, const QMatrix& W,
                   id<MTLBuffer> Y, uint32_t batch);
// Returns false if a piece refused to dispatch.
bool encodeQDecodeStep(id<MTLComputeCommandEncoder> enc, const QDecodeModel& m, DecodeState& s);

// ---- provided: reference solutions of earlier labs ----
void encodeGemvGather(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline, id<MTLBuffer> X,
                      id<MTLBuffer> W, id<MTLBuffer> Y, uint32_t batch, uint32_t in, uint32_t out);   // lab 22.1
void encodeGemvQ8_0(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline, id<MTLBuffer> X,
                    id<MTLBuffer> Wq, id<MTLBuffer> Wd, id<MTLBuffer> Y, uint32_t batch, uint32_t in,
                    uint32_t out);                                                                      // lab X2.1
void encodeGemvQ4_0(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline, id<MTLBuffer> X,
                    id<MTLBuffer> W, id<MTLBuffer> Y, uint32_t batch, uint32_t in, uint32_t out);   // lab X2.2
// decode.h declares encodeAddBias, encodeAddResidual (lab 2.3) and encodeSoftmaxRows,
// encodeArgmaxRows (lab 10.3; each returns false, without dispatching, if its pipeline cannot
// run 256 threads per threadgroup in whole SIMD-groups).
#endif
